CREATE TABLE notification_templates (id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,code TEXT NOT NULL,channel TEXT NOT NULL,locale TEXT NOT NULL,subject TEXT NOT NULL,content TEXT NOT NULL,status TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,UNIQUE(tenant_id,code,channel,locale));
CREATE TABLE notification_deliveries (id UUID PRIMARY KEY,tenant_id TEXT NOT NULL,template_code TEXT NOT NULL,channel TEXT NOT NULL,locale TEXT NOT NULL,recipient TEXT NOT NULL,variables JSONB NOT NULL,idempotency_key TEXT NOT NULL,status TEXT NOT NULL,provider TEXT NOT NULL DEFAULT '',provider_message_id TEXT NOT NULL DEFAULT '',failure_reason TEXT NOT NULL DEFAULT '',attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL,version BIGINT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,UNIQUE(tenant_id,idempotency_key));
CREATE INDEX notification_deliveries_dispatch_idx ON notification_deliveries(status,next_attempt_at,created_at); CREATE INDEX notification_deliveries_tenant_idx ON notification_deliveries(tenant_id,created_at DESC,id);
